// Apply a verified saved appearance before the first paint. Keep the dark
// default in sync with ThemeRuntime; never persist a default as a choice.
export function themeScript({
  allowed,
  deadline,
}: {
  allowed: boolean;
  deadline: string | null;
}) {
  const access = JSON.stringify({ allowed, deadline });
  return `(function(){var access=${access};var landing=location.pathname==='/';var pricing=location.pathname==='/pricing';var d=true;var a='purple';try{var t=localStorage.getItem('mailloop-theme');d=t!=='light';if(access.allowed&&(!access.deadline||Date.now()<Date.parse(access.deadline))&&localStorage.getItem('mailloop-appearance')==='vercel')a='vercel'}catch{}var r=document.documentElement;var w=!/^\\/usage\\/return\\/?$/.test(location.pathname)&&new RegExp('^/(compose|templates|contacts|history|usage|settings|billing)(/|$)').test(location.pathname);r.dataset.theme=d?'dark':'light';r.dataset.appearance=a;r.toggleAttribute('data-workspace',w);r.toggleAttribute('data-themed',!landing);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',!landing&&a==='vercel'?(d?'#0a0a0a':'#fafafa'):pricing?(d?'#07060d':'#f7f5ff'):d?'#0b0a14':landing?'#faf9fe':'#f6f5fb')})()`;
}
